// Object storage contract. Implementations: LocalStorage (dev), R2Storage (production).
export interface StorageProvider {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** Returns null when the object does not exist. */
  get(key: string): Promise<Buffer | null>;
  /** Idempotent: deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
}

/** Keys are generated by the server and look like "<coupleSpaceId>/<uuid>.webp".
 *  This check is a defence in depth against path traversal and odd characters. */
const KEY_PATTERN = /^[A-Za-z0-9_-]+(\/[A-Za-z0-9_-]+(\.[A-Za-z0-9]+)?)+$/;

export function assertSafeKey(key: string): void {
  if (key.length > 200 || !KEY_PATTERN.test(key) || key.includes("..")) {
    throw new Error("Unsafe storage key");
  }
}
